/** An import of one file per relative path; a folder-chosen import is named after `rootLabel`. */
async function project(paths: string[], rootLabel = 'Synthetic Secret Folder') {
    const files = paths.map(relativePath => ({ slotId: randomUUID(), filename: relativePath.split('/').at(-1)!, relativePath, byteLength: null }));
    return (await createAdminImport(by, { operationId: randomUUID(), manifest: { rootLabel: paths.some(path => path.includes('/')) ? rootLabel : '', files } })).item;
}
