test('confirming every selected file queues one automatic run under the uploader, fencing the import without touching its revision', async () => {
    const storage = new Storage(), item = await project(['Disc 1/01 Secret One.wav', 'Disc 1/02 Secret Two.wav']);
    const first = await upload(item, 0, { ...sharedFrames, TPE1: 'Per File One' }, storage);
    assert.equal(await lookup(item.id), null, 'a non-last confirmation queues nothing');
    const before = Date.now(), second = await upload(first.item, 1, { ...sharedFrames, TPE1: 'Per File Two' }, storage);
    const record = (await lookup(item.id))!;
    assert.deepEqual([record.run, record.state, record.automatic, record.grantSource, record.actorId, record.automaticRuns, record.input, record.queries], [1, 'queued', true, 'upload', by, 1,
        { trigger: 'tags', submitted: null }, [{ kind: 'musicBrainzReleaseSearch', query: albumQuery, basis: 'albumText' }, { kind: 'musicBrainzReleaseSearch', query: { release: 'Synthetic Album' }, basis: 'albumText' }]]);
    assert.ok(record.grantExpiresAt.getTime() >= before + 60 * 60 * 1000 && record.grantExpiresAt.getTime() <= Date.now() + 60 * 60 * 1000);
    const doc = await stored(item.id);
    assert.deepEqual(doc.lookupGate, { fence: 1, run: 1, state: 'queued', blocking: true });
    // The same uploads with lookup unconfigured end at the same revision, values and receipts.
    delete process.env.FINITUDE_ADMIN_METADATA_LOOKUP_CONTACT;
    const plain = await project(['Disc 1/01 Secret One.wav', 'Disc 1/02 Secret Two.wav']);
    const plainDone = await upload((await upload(plain, 0, { ...sharedFrames, TPE1: 'Per File One' }, storage)).item, 1, { ...sharedFrames, TPE1: 'Per File Two' }, storage);
    const plainDoc = await stored(plain.id);
    assert.deepEqual([second.item.revision, second.item.valueRevision, doc.receipts.map(receipt => receipt.kind), doc.automaticReceipts ?? []],
        [plainDone.item.revision, plainDone.item.valueRevision, plainDoc.receipts.map(receipt => receipt.kind), plainDoc.automaticReceipts ?? []]);
    assert.equal(plainDoc.lookupGate, undefined);
    assert.equal(await lookup(plain.id), null);
    // The editor's projection never carries the fence.
    assert.deepEqual(Object.keys(second.item).sort(), Object.keys(plainDone.item).sort());
    assert.equal(JSON.stringify(second.item).includes('lookupGate'), false);
});

