test('without usable tags the cleaned folder name is used once per project, and files chosen without a folder send nothing', async () => {
    const storage = new Storage(), item = await project(['CD1/01 Secret One.wav'], 'Synthetic Artist - Synthetic Folder [FLAC 24bit]');
    const uploaded = await upload(item, 0, { TRCK: '1' }, storage);
    const first = (await lookup(item.id))!;
    const folderQueries = first.queries.map(query => query.kind === 'musicBrainzReleaseSearch' ? query.query : null);
    assert.deepEqual([first.input.trigger, first.folderUsed, folderQueries],
        ['folder', false, [{ artist: 'Synthetic Artist', release: 'Synthetic Folder' }, { release: 'Synthetic Artist - Synthetic Folder' }]]);
    // Replaced before any request: the folder name was never sent, so the rerun still uses it.
    const removed = await cleanupAdminImportAsset(by, item.id, slotOf(item, 0), mutation(uploaded.item.revision), storage);
    await upload(removed.item, 0, { TRCK: '1' }, storage, mutation(removed.item.revision));
    const second = (await lookup(item.id))!;
    assert.deepEqual([second.run, second.state, second.input.trigger, second.queries, second.folderUsed, second.automaticRuns], [2, 'queued', 'folder', first.queries, false, 2]);
    const sent = fixtureClient(folderQueries.map(query => searchAnswer(query!, [])));
    await drain({ musicBrainz: sent.musicBrainz });
    assert.deepEqual([(await lookup(item.id))!.outcome, (await lookup(item.id))!.folderUsed, sent.requests.length], ['noRelease', true, 2]);
    // Once sent, a changed file set reruns without it.
    const again = await cleanupAdminImportAsset(by, item.id, slotOf(item, 0), mutation((await getAdminImport(by, item.id)).item.revision), storage);
    await upload(again.item, 0, { TRCK: '1' }, storage, mutation(again.item.revision));
    const third = (await lookup(item.id))!;
    assert.deepEqual([third.run, third.state, third.outcome, third.queries, third.folderUsed, third.automaticRuns], [3, 'complete', 'noQuery', [], true, 3]);
    const loose = await project(['01 Secret One.wav']);
    await upload(loose, 0, { TRCK: '1' }, storage);
    const none = (await lookup(loose.id))!;
    assert.deepEqual([none.state, none.outcome, none.queries, (await stored(loose.id)).lookupGate], ['complete', 'noQuery', [], { fence: 1, run: 1, state: 'complete', blocking: false }]);
    const client = fixtureClient([]);
    await drain({ musicBrainz: client.musicBrainz });
    assert.deepEqual(client.requests, []);
});

