test('a role loss, a deleted account or an expired grant stops the run, discarding the step that found it', async () => {
    const synthetic = () => [searchAnswer(albumQuery, [mbid(1), mbid(2)]), searchAnswer({ release: 'Synthetic Album' }, []), releaseAnswer(mbid(1), [1000]), releaseAnswer(mbid(2), [1000])];
    const run = async (prepare: (id: string) => Promise<void>, client: MusicBrainzClient, now?: () => Date) => {
        const id = await seeded(1, () => v2({ album: 'Synthetic Album', albumArtists: ['Synthetic Ensemble'] }));
        await requestAutomaticMetadataLookup(by, id, 'upload');
        await prepare(id);
        await drain({ musicBrainz: client, ...(now ? { now } : {}) });
        return { record: (await lookup(id))!, gate: (await stored(id)).lookupGate! };
    };
    const users = getDb()!.collection('users');
    const demoted = fixtureClient(synthetic());
    const lost = await run(async () => { await users.updateOne({ _id: actor }, { $set: { role: 'user' } }); }, demoted.musicBrainz);
    assert.deepEqual([lost.record.state, lost.record.issue, demoted.requests.length, lost.record.ranking, lost.gate.blocking], ['stopped', 'permissionLost', 0, null, false]);
    await users.updateOne({ _id: actor }, { $set: { role: 'admin' } });

    // Demoted while a details request is in flight: that answer is never stored.
    const midway = fixtureClient(synthetic());
    const wrapped: MusicBrainzClient = { ...midway.musicBrainz, async lookupRelease(releaseId, options) {
        const release = await midway.musicBrainz.lookupRelease(releaseId, options); await users.updateOne({ _id: actor }, { $set: { role: 'user' } }); return release;
    } };
    const mid = await run(async () => undefined, wrapped);
    assert.deepEqual([mid.record.state, mid.record.issue, mid.record.candidates.map(candidate => candidate.details), mid.record.ranking, midway.requests.length],
        ['stopped', 'permissionLost', ['pending', 'pending'], null, 3]);
    await users.updateOne({ _id: actor }, { $set: { role: 'admin' } });

    const deleted = fixtureClient(synthetic());
    const gone = await run(async () => { await users.deleteOne({ _id: actor }); }, deleted.musicBrainz);
    assert.deepEqual([gone.record.state, gone.record.issue, deleted.requests.length], ['stopped', 'permissionLost', 0]);
    await users.insertOne({ _id: actor, email: 'lookup-admin@example.test', role: 'admin' });

    const expired = fixtureClient(synthetic());
    const late = await run(async () => undefined, expired.musicBrainz, () => later(60 * 60 * 1000 + 1000));
    assert.deepEqual([late.record.state, late.record.issue, expired.requests.length, late.gate], ['stopped', 'grantExpired', 0, { fence: 2, run: 1, state: 'stopped', blocking: false }]);
});

test('a rate-limited source is retried after its Retry-After within seconds, then after 2 and 5 minutes, then reported unavailable (sourceBusy), never as no release, until a manual retry', async () => {
    const id = await seeded(1, () => v2({ album: 'Synthetic Album', albumArtists: ['Synthetic Ensemble'] }));
    await requestAutomaticMetadataLookup(by, id, 'upload');
    // Every attempt answers 503 without a Retry-After: each call's three attempts end on the 5-second backoff it would have waited.
    const failing = fixtureClient(unavailable(searchUrl(albumQuery), 12));
    let now = new Date();
    const retryAts: number[] = [];
    for (const delay of [5_000, 120_000, 300_000]) {
        await runMetadataLookupOnce({ musicBrainz: failing.musicBrainz, now: () => now });
        const record = (await lookup(id))!;
        assert.deepEqual([record.state, record.issue, record.leaseOwner, record.outcome], ['retrying', 'sourceBusy', null, null]);
        assert.equal(record.retryAt!.getTime(), now.getTime() + delay);
        retryAts.push(record.retryAt!.getTime());
        assert.equal(await runMetadataLookupOnce({ musicBrainz: failing.musicBrainz, now: () => later(-1, record.retryAt!) }), false, 'not due yet');
        now = record.retryAt!;
    }
    await runMetadataLookupOnce({ musicBrainz: failing.musicBrainz, now: () => now });
    const gaveUp = (await lookup(id))!;
    assert.deepEqual([gaveUp.state, gaveUp.issue, gaveUp.outcome, gaveUp.ranking, gaveUp.attempts, failing.requests.length, (await stored(id)).lookupGate!.blocking],
        ['unavailable', 'sourceBusy', null, null, { musicbrainz: 4, itunes: 0 }, 12, false]);
    // Another administrator retries manually: the same queries run under that administrator's grant.
    const retried = await queue(byOther, id, () => ({ kind: 'retry', actorId: byOther, operationId: randomUUID() }));
    assert.deepEqual([retried.run, retried.grantSource, retried.actorId, retried.automatic, retried.automaticRuns, retried.queries], [2, 'retry', byOther, false, 1, gaveUp.queries]);
    const working = fixtureClient([searchAnswer(albumQuery, [mbid(1)]), searchAnswer({ release: 'Synthetic Album' }, [mbid(1)]), releaseAnswer(mbid(1), [1000])]);
    await drain({ musicBrainz: working.musicBrainz });
    assert.deepEqual([(await lookup(id))!.state, (await lookup(id))!.outcome], ['complete', 'candidates']);
});

