    let aborted = false;
    const holding: MusicBrainzClient = { ...first.musicBrainz, async searchReleases(query, options) {
        if (!query.artist) {
            entered();
            return new Promise((_resolve, reject) => options.signal.addEventListener('abort', () => { aborted = true; reject(new MetadataLookupSourceError('musicbrainz', 'cancelled')); }, { once: true }));
        }
        return first.musicBrainz.searchReleases(query, options);
    } };
    const stop = startMetadataLookupWorker({ musicBrainz: holding }, 5);
    await inFlight;
    await stop();
    const paused = (await lookup(id))!;
    assert.deepEqual([aborted, paused.state, paused.leaseOwner, paused.leaseUntil, paused.queryIndex, paused.candidates.length], [true, 'running', null, null, 1, 1]);
    const resumed = fixtureClient([searchAnswer({ release: 'Synthetic Album' }, [mbid(1), mbid(2)]), releaseAnswer(mbid(1), [1000]), releaseAnswer(mbid(2), [1000])]);
    await drain({ musicBrainz: resumed.musicBrainz });
