    assert.deepEqual([superseded.state, superseded.issue, superseded.staleSlotIds, (await stored(item.id)).lookupGate], ['superseded', 'fileSetChanged', [slotOf(item, 0)],
        { fence: 2, run: 1, state: 'superseded', blocking: false }]);
    latest = await upload(removed.item, 0, sharedFrames, storage, mutation(removed.item.revision));
    assert.deepEqual([(await lookup(item.id))!.run, (await lookup(item.id))!.automaticRuns, (await lookup(item.id))!.state], [2, 2, 'queued']);
    // A completed run keeps its result and records the stale file; draft values stay as they are.
    const client = fixtureClient([searchAnswer(albumQuery, []), searchAnswer({ release: 'Synthetic Album' }, [])]);
    await drain({ musicBrainz: client.musicBrainz });
    assert.deepEqual([(await lookup(item.id))!.state, (await lookup(item.id))!.outcome], ['complete', 'noRelease']);
    const draft = (await stored(item.id)).draft, current = (await getAdminImport(by, item.id)).item;
