test('saves, decisions, candidates and analysis succeed while a run is queued, running or unavailable', async () => {
    const storage = new Storage(), item = await project(['Disc 1/01 Secret One.wav', 'Disc 1/02 Secret Two.wav']);
    await upload((await upload(item, 0, sharedFrames, storage)).item, 1, sharedFrames, storage);
    const work = async (label: string) => {
        const current = (await getAdminImport(by, item.id)).item;
        const saved = await editAdminImport(by, item.id, { ...mutation(current.revision), changes: [{ path: 'album.title', base: current.draft.album.title, value: `Typed ${label}` }] });
        const decided = await decideAdminImportDuplicates(byOther, item.id, { ...mutation(saved.item.revision), decisions: [albumDecision] });
        assert.ok(await adminImportDuplicateCandidates(by, item.id), label);
        assert.deepEqual([decided.item.draft.album.title, decided.item.decisions.length], [`Typed ${label}`, 1], label);
    };
    assert.equal((await lookup(item.id))!.state, 'queued');
    await work('queued');
    // The request in flight ends with the contact removed, so the run ends unavailable once it is released.
    let release!: () => void, entered!: () => void;
    const held = new Promise<void>(resolve => { release = resolve; }), inFlight = new Promise<void>(resolve => { entered = resolve; });
    const contactRemoved: MusicBrainzClient = { ...fixtureClient([]).musicBrainz, async searchReleases() { entered(); await held; throw new MetadataLookupSourceError('musicbrainz', 'notConfigured'); } };
    const worker = runMetadataLookupOnce({ musicBrainz: contactRemoved });
    await inFlight;
    assert.equal((await lookup(item.id))!.state, 'running');
    await work('running');
    const luna: ImportAnalysisProvider = { configured: () => true, analyze: async () => [] };
    assert.equal((await analyzeAdminImport(by, item.id, mutation((await getAdminImport(by, item.id)).item.revision), luna)).item.analysis.state, 'queued');
    release();
    assert.equal(await worker, true);
    const ended = (await lookup(item.id))!;
    assert.deepEqual([ended.state, ended.issue, ended.attempts, ended.retryAt, (await stored(item.id)).lookupGate!.blocking], ['unavailable', 'notConfigured', { musicbrainz: 0, itunes: 0 }, null, false]);
    await work('unavailable');
});

