test('a timed-out or unexpected failure is retried after 30 seconds, a throttled one within seconds, a refused gate keeps a longer Retry-After up to a minute, and busy answers through every retry end the run busy', async () => {
    const failWith = async (failure: () => Error, ticks: number) => {
        // Earlier cases' retrying runs would become due at the advanced clock, so each case runs alone.
        await adminImportLookupCollection().deleteMany({});
        const id = await seeded(1, syntheticAlbum);
        await requestAutomaticMetadataLookup(by, id, 'upload');
        const start = new Date();
        let calls = 0, now = start;
        const failing: MusicBrainzClient = { ...fixtureClient([]).musicBrainz, async searchReleases() { calls++; throw failure(); } };
        for (let tick = 0; tick < ticks; tick++) {
            await runMetadataLookupOnce({ musicBrainz: failing, now: () => now });
            now = (await lookup(id))!.retryAt ?? now;
        }
        return { record: (await lookup(id))!, calls, start };
    };
    // The step deadline aborts a slow request as cancelled; while the worker is not stopping, that is an unavailable source.
    const failures: [string, () => Error][] = [['deadline', () => new MetadataLookupSourceError('musicbrainz', 'cancelled')],
        ['invalid response', () => new MetadataLookupSourceError('musicbrainz', 'invalidResponse')], ['unexpected', () => new Error('synthetic transport defect')]];
    for (const [label, failure] of failures) {
        const { record, calls, start } = await failWith(failure, 1);
        assert.deepEqual([record.state, record.issue, record.attempts, record.retryAt!.getTime() - start.getTime(), record.leaseOwner, calls],
            ['retrying', 'sourceUnavailable', { musicbrainz: 1, itunes: 0 }, 30_000, null, 1], label);
    }
    // A throttled source (503/429) is busy, and its first retry follows the Retry-After within 2 to 10 seconds.
    for (const [retryAfterMs, delay] of [[45_000, 10_000], [600_000, 10_000], [3_000, 3_000], [null, 2_000]] as const) {
        const limited = await failWith(() => new MetadataLookupSourceError('musicbrainz', 'rateLimited', retryAfterMs), 1);
        assert.deepEqual([limited.record.state, limited.record.issue, limited.record.retryAt!.getTime() - limited.start.getTime()], ['retrying', 'sourceBusy', delay], String(retryAfterMs));
    }
    // A refused gate keeps the 30-second schedule, or a longer Retry-After of at most a minute.
    const refused = await failWith(() => new MetadataLookupSourceError('musicbrainz', 'busy', 45_000), 1);
    assert.deepEqual([refused.record.issue, refused.record.retryAt!.getTime() - refused.start.getTime()], ['sourceBusy', 45_000]);
    const clamped = await failWith(() => new MetadataLookupSourceError('musicbrainz', 'busy', 600_000), 1);
    assert.equal(clamped.record.retryAt!.getTime() - clamped.start.getTime(), 60_000);
    const busy = await failWith(() => new MetadataLookupSourceError('musicbrainz', 'busy'), 4);
    assert.deepEqual([busy.record.state, busy.record.issue, busy.record.outcome, busy.record.ranking, busy.record.attempts, busy.record.retryAt, busy.calls],
        ['unavailable', 'sourceBusy', null, null, { musicbrainz: 4, itunes: 0 }, null, 4]);
});

test('a grant that expires between steps stops the run, keeping earlier candidates unranked and discarding the step that found it', async () => {
    const id = await seeded(1, syntheticAlbum);
    await requestAutomaticMetadataLookup(by, id, 'upload');
    const client = fixtureClient([searchAnswer(albumQuery, [mbid(1)]), searchAnswer({ release: 'Synthetic Album' }, [mbid(2)])]);
    const start = new Date(), expired = later(60 * 60 * 1000 + 1000, start);
    // The claim and the first two steps read the clock in time; the third step finds the grant expired.
    let reads = 0;
    assert.equal(await runMetadataLookupOnce({ musicBrainz: client.musicBrainz, now: () => ++reads <= 3 ? start : expired }), true);
    const record = (await lookup(id))!;
    assert.deepEqual([record.state, record.issue, record.candidates.map(candidate => [candidate.releaseId, candidate.details]), record.queryIndex, record.ranking, record.outcome, client.requests.length],
        ['stopped', 'grantExpired', [[mbid(1), 'pending']], 1, null, null, 2]);
    assert.deepEqual((await stored(id)).lookupGate, { fence: 3, run: 1, state: 'stopped', blocking: false });
    // A stopped run is never claimed again.
    assert.equal(await runMetadataLookupOnce({ musicBrainz: client.musicBrainz, now: () => expired }), false);
});

test('a submission replaces an active run whose late answer is discarded, a retry repeats it, and malformed or closed requests are refused', async () => {
    const id = await seeded(1, syntheticAlbum);
    const malformed: [string, () => MetadataLookupRequest, string][] = [
        ['account', () => ({ kind: 'submit', actorId: 'not-an-account', operationId: randomUUID(), submitted: { kind: 'album', text: 'Synthetic Album' } }), 'ADMIN_IMPORT_INVALID_INPUT'],
        ['intent', () => ({ kind: 'retry', actorId: by, operationId: 'not-an-intent' }), 'ADMIN_IMPORT_INVALID_INPUT'],
        ['kind', () => ({ kind: 'submit', actorId: by, operationId: randomUUID(), submitted: { kind: 'artist' as 'album', text: 'Synthetic Album' } }), 'ADMIN_IMPORT_LOOKUP_INVALID_NAME'],
        ['request kind', () => ({ kind: 'choose', actorId: by, operationId: randomUUID() }) as unknown as MetadataLookupRequest, 'ADMIN_IMPORT_INVALID_INPUT'],
        ['non-administrator grant', () => ({ kind: 'submit', actorId: listener.toHexString(), operationId: randomUUID(), submitted: { kind: 'album', text: 'Synthetic Album' } }), 'ADMIN_IMPORT_ADMIN_REQUIRED'],
        ['missing account grant', () => ({ kind: 'retry', actorId: new ObjectId().toHexString(), operationId: randomUUID() }), 'ADMIN_IMPORT_ADMIN_REQUIRED']
    ];
    const listener = new ObjectId();
    await getDb()!.collection('users').insertOne({ _id: listener, email: 'lookup-listener@example.test', role: 'user' });
    for (const [label, request, expected] of malformed) await assert.rejects(queue(by, id, request), code(expected), label);
    assert.deepEqual([await lookup(id), (await stored(id)).lookupGate], [null, undefined]);

    await requestAutomaticMetadataLookup(by, id, 'upload');
    const first = fixtureClient([searchAnswer(albumQuery, [mbid(1)])]), held = holdFirstSearch(first.musicBrainz);
    const worker = runMetadataLookupOnce({ musicBrainz: held.musicBrainz });
    await held.inFlight;
    const submitted = await queue(byOther, id, submit('Typed Album'));
    assert.deepEqual([submitted.run, submitted.state, submitted.automaticRuns, submitted.grantSource, (await stored(id)).lookupGate],
        [2, 'queued', 1, 'submit', { fence: 3, run: 2, state: 'queued', blocking: true }]);
    held.release();
    assert.equal(await worker, true);
    assert.deepEqual(await lookup(id), submitted);
    const answers = () => [searchAnswer({ release: 'Typed Album', artist: 'Synthetic Ensemble' }, [mbid(2)]), searchAnswer({ release: 'Typed Album' }, []), releaseAnswer(mbid(2), [1000])];
    await drain({ musicBrainz: fixtureClient(answers()).musicBrainz });
    assert.deepEqual([(await lookup(id))!.state, (await lookup(id))!.candidates.map(candidate => candidate.releaseId)], ['complete', [mbid(2)]]);
    // A retry repeats the submitted text's queries under the retrying administrator's grant.
    const retried = await queue(by, id, () => ({ kind: 'retry', actorId: by, operationId: randomUUID() }));
    assert.deepEqual([retried.run, retried.grantSource, retried.actorId, retried.automatic, retried.input, retried.queries, retried.candidates], [3, 'retry', by, false, submitted.input, submitted.queries, []]);
    // A manual retry waits for the gate on every request, even while it is held elsewhere.
    const retryModes: string[] = [];
    const replay = fixtureClient(answers(), recordingGate(retryModes, true));
    await drain({ musicBrainz: replay.musicBrainz });
    assert.deepEqual([(await lookup(id))!.state, replay.requests.length, retryModes], ['complete', 3, ['wait', 'wait', 'wait']]);
    // A stored input this release cannot read is not retried.
    await adminImportLookupCollection().updateOne({ _id: new ObjectId(id) }, { $set: { input: { trigger: 'later', submitted: null } as never } });
    await assert.rejects(queue(by, id, () => ({ kind: 'retry', actorId: by, operationId: randomUUID() })), code('ADMIN_IMPORT_LOOKUP_NOTHING_TO_RETRY'));

    // A run that planned nothing has nothing to retry, and a locked project refuses every request without a fence write.
    const loose = await seeded(1, () => v2(), { folder: false });
    assert.equal((await requestAutomaticMetadataLookup(by, loose, 'upload')).reason, 'noQuery');
    await assert.rejects(queue(by, loose, () => ({ kind: 'retry', actorId: by, operationId: randomUUID() })), code('ADMIN_IMPORT_LOOKUP_NOTHING_TO_RETRY'));
    await projects().updateOne({ _id: new ObjectId(loose) }, { $set: { 'media.publication': preparingPublication() } });
    const gate = (await stored(loose)).lookupGate;
    await assert.rejects(queue(by, loose, submit('Synthetic Album')), code('ADMIN_IMPORT_LOOKUP_REFUSED'));
    assert.deepEqual((await stored(loose)).lookupGate, gate);
});

test('a run whose stored progress cannot be advanced is retried after its lease and stays bounded by its grant', async () => {
    const id = await seeded(1, syntheticAlbum);
    await requestAutomaticMetadataLookup(by, id, 'upload');
    // A bound file set this release cannot read, as a later release might store it: every step fails before anything is stored.
    await adminImportLookupCollection().updateOne({ _id: new ObjectId(id) }, { $set: { files: 'unreadable' as never } });
    const client = fixtureClient([]);
    await assert.rejects(runMetadataLookupOnce({ musicBrainz: client.musicBrainz }));
    assert.deepEqual([(await lookup(id))!.state, (await stored(id)).lookupGate!.fence], ['queued', 1]);
    // The grant check comes first, so once the grant has expired the next claim ends the run without a request.
    await drain({ musicBrainz: client.musicBrainz, now: () => later(60 * 60 * 1000 + 1000) });
    const record = (await lookup(id))!;
    assert.deepEqual([record.state, record.issue, record.leaseOwner, client.requests.length, (await stored(id)).lookupGate],
        ['stopped', 'grantExpired', null, 0, { fence: 2, run: 1, state: 'stopped', blocking: false }]);

    // Bound entries this release cannot read never block removing a file: they are skipped, and nothing is marked stale.
    const storage = new Storage(), item = await project(['Disc 1/01 Secret One.wav', 'Disc 1/02 Secret Two.wav']);
    const done = await upload((await upload(item, 0, sharedFrames, storage)).item, 1, sharedFrames, storage);
    await adminImportLookupCollection().updateOne({ _id: new ObjectId(item.id) }, { $set: { files: [null, 'unreadable', { slotId: 5, operationId: 'o' }] as never } });
    const removed = await cleanupAdminImportAsset(by, item.id, slotOf(item, 0), mutation(done.item.revision), storage);
    assert.equal(removed.item.assets.some(asset => asset.slotId === slotOf(item, 0) && asset.state === 'ready'), false);
    const kept = (await lookup(item.id))!;
    assert.deepEqual([kept.state, kept.staleSlotIds, (await stored(item.id)).lookupGate!.fence], ['queued', [], 1]);
});

test('a manual retry replaces a run waiting for an automatic retry and waits for the gate, and a retry past the grant ends the run unavailable', async () => {
    const id = await seeded(1, syntheticAlbum);
    await requestAutomaticMetadataLookup(by, id, 'upload');
    await runMetadataLookupOnce({ musicBrainz: fixtureClient(unavailable(searchUrl(albumQuery), 3)).musicBrainz });
    assert.equal((await lookup(id))!.state, 'retrying');
    const retried = await queue(byOther, id, () => ({ kind: 'retry', actorId: byOther, operationId: randomUUID() }));
    assert.deepEqual([retried.run, retried.state, retried.grantSource, retried.attempts, retried.retryAt, (await stored(id)).lookupGate],
        [2, 'queued', 'retry', { musicbrainz: 0, itunes: 0 }, null, { fence: 4, run: 2, state: 'queued', blocking: true }]);
    const modes: string[] = [];
    const working = fixtureClient([searchAnswer(albumQuery, [mbid(1)]), searchAnswer({ release: 'Synthetic Album' }, []), releaseAnswer(mbid(1), [1000])], recordingGate(modes, true));
    await drain({ musicBrainz: working.musicBrainz });
    assert.deepEqual([(await lookup(id))!.state, modes], ['complete', ['wait', 'wait', 'wait']]);

    // Four seconds before the grant ends, even the throttled first retry (after 5 seconds) would come after it: retries count as
    // exhausted and Publish stops waiting.
    const late = await seeded(1, syntheticAlbum);
    await requestAutomaticMetadataLookup(by, late, 'upload');
    const nearEnd = later(-4_000, (await lookup(late))!.grantExpiresAt);
    await runMetadataLookupOnce({ musicBrainz: fixtureClient(unavailable(searchUrl(albumQuery), 3)).musicBrainz, now: () => nearEnd });
    const ended = (await lookup(late))!;
    assert.deepEqual([ended.state, ended.issue, ended.retryAt, ended.attempts, ended.outcome, (await stored(late)).lookupGate],
        ['unavailable', 'sourceBusy', null, { musicbrainz: 1, itunes: 0 }, null, { fence: 3, run: 1, state: 'unavailable', blocking: false }]);
    // Ten seconds before the grant ends, an outage's 30-second retry would come after it too: the run ends unavailable at once.
    const outage = await seeded(1, syntheticAlbum);
    await requestAutomaticMetadataLookup(by, outage, 'upload');
    const tenBefore = later(-10_000, (await lookup(outage))!.grantExpiresAt);
    const down: MusicBrainzClient = { ...fixtureClient([]).musicBrainz, async searchReleases() { throw new MetadataLookupSourceError('musicbrainz', 'unavailable'); } };
    await runMetadataLookupOnce({ musicBrainz: down, now: () => tenBefore });
    const gone = (await lookup(outage))!;
    assert.deepEqual([gone.state, gone.issue, gone.retryAt, gone.attempts, gone.outcome, (await stored(outage)).lookupGate],
        ['unavailable', 'sourceUnavailable', null, { musicbrainz: 1, itunes: 0 }, null, { fence: 3, run: 1, state: 'unavailable', blocking: false }]);
});

